// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/organizations", wrapper.ListOrganizations)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/organizations", wrapper.CreateOrganization)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/organizations/{orgId}", wrapper.GetOrganization)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/organizations/{orgId}", wrapper.PatchOrganization)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/organizations/{orgId}/entitlement", wrapper.GetEntitlement)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/organizations/{orgId}/usage", wrapper.GetUsage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/organizations/{orgId}/invitations", wrapper.ListInvitations)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/organizations/{orgId}/invitations", wrapper.CreateInvitation)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/invitations/{invitation}", wrapper.RevokeInvitation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/invitations/{invitation}", wrapper.PreviewInvitation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/invitations/{token}:accept", wrapper.AcceptInvitation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/operations/{operationId}", wrapper.GetOperation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/operations/{operationId}:retry", wrapper.RetryOperation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/organizations", wrapper.AdminListOrganizations)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/organizations/{orgId}:approve", wrapper.ApproveOrganization)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/organizations/{orgId}:reject", wrapper.RejectOrganization)
	})

	return r
}

